SELECT
    SUM(CASE WHEN t.task_status = '1' THEN 1 ELSE 0 END) AS successCount,
    SUM(CASE WHEN t.task_status IN ('2', '4') THEN 1 ELSE 0 END) AS failCount,
    COUNT(*) AS totalCount,
    SUM(CASE WHEN t.task_status = '3' THEN 1 ELSE 0 END) AS runningCount,
    SUM(CASE WHEN t.task_status = '0' THEN 1 ELSE 0 END) AS waitingCount
FROM
    vm_air_task_t t
left join vm_air_line_t l on l.flight_route_id = t.flight_route_id
LEFT JOIN vm_uav_device_info_t dt ON t.uav_code = dt.device_code  COLLATE utf8mb4_general_ci
WHERE
  DATE_FORMAT(t.plan_time,'%Y-%m-%d %H:%i:%s') >= #{startTime}
  and DATE_FORMAT(t.plan_time,'%Y-%m-%d %H:%i:%s') <= #{endTime}
  AND t.delete_flag = '0'

        and dt.province_code = #{provinceCode}


        and dt.city_code = #{cityCode}


        and dt.county_code = #{countyCode}

  ${dataScope}

SELECT
    DATE_FORMAT(t.plan_time,'%H') AS showTime,
    COUNT(*) AS totalCount
FROM
    vm_air_task_t t
    left join vm_air_line_t l on l.flight_route_id = t.flight_route_id
    LEFT JOIN vm_uav_device_info_t dt ON t.uav_code = dt.device_code  COLLATE utf8mb4_general_ci
WHERE
    DATE_FORMAT(t.plan_time,'%Y-%m-%d %H:%i:%s') >= #{startTime}
  and DATE_FORMAT(t.plan_time,'%Y-%m-%d %H:%i:%s') <= #{endTime}
  AND t.delete_flag = '0' AND !ISNULL(plan_time)

        and dt.province_code = #{provinceCode}


        and dt.city_code = #{cityCode}


        and dt.county_code = #{countyCode}

    ${dataScope}
GROUP BY
    HOUR(plan_time)
ORDER BY
    showTime;

SELECT
    DATE(plan_time) AS showTime,
    COUNT(*) AS totalCount
FROM
    vm_air_task_t t
    left join vm_air_line_t l on l.flight_route_id = t.flight_route_id
    LEFT JOIN vm_uav_device_info_t dt ON t.uav_code = dt.device_code  COLLATE utf8mb4_general_ci
WHERE
    DATE_FORMAT(t.plan_time,'%Y-%m-%d %H:%i:%s') >= #{startTime}
  and DATE_FORMAT(t.plan_time,'%Y-%m-%d %H:%i:%s') <= #{endTime}
  AND t.delete_flag = '0' AND !ISNULL(plan_time)

        and dt.province_code = #{provinceCode}


        and dt.city_code = #{cityCode}


        and dt.county_code = #{countyCode}

    ${dataScope}
GROUP BY
    DATE(plan_time)
ORDER BY
    showTime;

SELECT t.plan_task_id as taskId, CASE WHEN l.flight_main_type = '1' THEN CONCAT('指哪飞哪', DATE_FORMAT(t.plan_time, '%Y%m%d%H%i%s')) WHEN l.flight_main_type = '2' THEN CONCAT('一键起飞', DATE_FORMAT(t.plan_time, '%Y%m%d%H%i%s')) ELSE t.plan_Name END as taskName, DATE_FORMAT(t.plan_time, '%Y-%m-%d %H:%i' ) as planTime,t.task_status as taskStatus, (case when length(IFNULL(rel.device_name, '')) = 0 then dt.device_name else rel.device_name end ) as uavName,l.flight_main_type as flightMainType FROM vm_air_task_t t left join vm_air_line_t l on l.flight_route_id = t.flight_route_id LEFT JOIN vm_uav_device_info_t dt ON t.uav_code = dt.device_code COLLATE utf8mb4_general_ci LEFT JOIN vm_tenant_device_common_rel_t rel ON rel.device_code = dt.device_code and rel.tenant_id = #{tenantId} and rel.industry_code = #{industryCode} and rel.delete_flag = '0' and rel.device_type = 1 WHERE DATE_FORMAT(t.plan_time,'%Y-%m-%d %H:%i:%s') >= #{startTime} and DATE_FORMAT(t.plan_time,'%Y-%m-%d %H:%i:%s') <= #{endTime} AND t.delete_flag = '0'
and dt.province_code = #{provinceCode}
and dt.city_code = #{cityCode}
and dt.county_code = #{countyCode}
${dataScope} ORDER BY CASE WHEN t.task_status = '1' THEN 1 WHEN t.task_status = '3' THEN 2 WHEN t.task_status = '0' THEN 3 WHEN t.task_status IN ('2', '4') THEN 4 ELSE 5 END, planTime asc

