mapper.select:
WITH uav_usage AS ( SELECT count(1) as uav_usage_count FROM vm_air_task_t t LEFT JOIN vm_air_line_t l on l.flight_route_id = t.flight_route_id
WHERE
), executed_plans AS ( SELECT COUNT(DISTINCT t.plan_id) as executed_plan_count FROM vm_air_task_t t LEFT JOIN vm_air_plan_t p ON p.plan_id = t.plan_id LEFT JOIN vm_air_line_t l on l.flight_route_id = t.flight_route_id
WHERE
AND t.task_status IN(1,2,3,4) AND p.delete_flag = 0 ), flight_count AS ( SELECT count(1) as flight_count FROM vm_air_task_t t LEFT JOIN vm_air_line_t l on l.flight_route_id = t.flight_route_id
WHERE
and task_status IN(1,2,3,4) ), flight_distance AS ( SELECT COALESCE(ROUND(sum(t.accumulate_mileage), 2), 0) as total_distance FROM vm_air_task_t t LEFT JOIN vm_air_line_t l on l.flight_route_id = t.flight_route_id
WHERE
), flight_duration AS ( SELECT COALESCE(ROUND(sum(t.fly_time) / 60, 2), 0) as total_duration FROM vm_air_task_t t LEFT JOIN vm_air_line_t l on l.flight_route_id = t.flight_route_id
WHERE
) SELECT COALESCE(u.uav_usage_count) as uavUsageCount, COALESCE(e.executed_plan_count) as executedPlanCount, COALESCE(f.flight_count) as flightCount, COALESCE(d.total_distance) as totalDistance, COALESCE(t.total_duration) as totalDuration FROM uav_usage u, executed_plans e, flight_count f, flight_distance d, flight_duration t;

SELECT dt.device_code as deviceCode, dt.device_name as deviceName, COALESCE(ROUND(sum(t.accumulate_mileage), 2), 0) as airMileage FROM vm_air_task_t t LEFT JOIN vm_air_line_t l on l.flight_route_id = t.flight_route_id LEFT JOIN vm_uav_device_info_t dt ON t.uav_code = dt.device_code COLLATE utf8mb4_general_ci
WHERE
GROUP BY t.uav_code ORDER BY airMileage desc LIMIT 5;

SELECT dt.device_code as deviceCode, dt.device_name as deviceName, COALESCE(ROUND(sum(t.fly_time) / 60, 2), 0) as flyTime FROM vm_air_task_t t LEFT JOIN vm_air_line_t l on l.flight_route_id = t.flight_route_id LEFT JOIN vm_uav_device_info_t dt ON t.uav_code = dt.device_code COLLATE utf8mb4_general_ci
WHERE
GROUP BY t.uav_code ORDER BY flyTime desc LIMIT 5;

SELECT dt.device_code as deviceCode, dt.device_name as deviceName, p.plan_name AS planName, count(1) as flyCount FROM vm_air_task_t t LEFT JOIN vm_air_plan_t p ON p.plan_id = t.plan_id LEFT JOIN vm_air_line_t l on l.flight_route_id = t.flight_route_id LEFT JOIN vm_uav_device_info_t dt ON t.uav_code = dt.device_code COLLATE utf8mb4_general_ci
WHERE
and task_status IN(1,2,3,4) and t.plan_id is not null and t.plan_id != '' GROUP BY p.plan_id,dt.device_code,dt.device_name,p.plan_name ORDER BY flyCount desc LIMIT 5;

SELECT (CASE WHEN l.flight_main_type = '0' THEN '计划飞行' WHEN l.flight_main_type = '1' THEN '指点飞行' WHEN l.flight_main_type = '2' THEN '一键起飞' END) as flightMainType, count(1) as totalCount FROM vm_air_task_t t LEFT JOIN vm_air_line_t l on l.flight_route_id = t.flight_route_id
WHERE
and task_status IN(1,2,3,4) and l.flight_main_type IS NOT NULL GROUP BY l.flight_main_type;

SELECT dataTable.flight_route_id, dataTable.task_record_id, dataTable.warning_type_id, dataTable.alarm_body from ${tableName} as dataTable
dataTable.delete_flag = '0' AND dataTable.tenant_id = #{tenantId} AND dataTable.industry_code = #{industryCode} AND dataTable.task_record_id IN
#{item}
